class Solution {
  private int[] lc, rc, cnt;
  private int nodes = 1;
  private static final int BITS = 17;

  private int merge(int a, int b, int level) {
    if (a == 0) return b;
    if (b == 0) return a;
    if (level == 0) {
      cnt[a] = 1;
      return a;
    }
    lc[a] = merge(lc[a], lc[b], level - 1);
    rc[a] = merge(rc[a], rc[b], level - 1);
    cnt[a] = cnt[lc[a]] + cnt[rc[a]];
    return a;
  }

  public int[] kthSmallest(int[] par, int[] vals, int[][] queries) {
    int n = par.length;
    int cap = n * (BITS + 1) + 5;
    lc = new int[cap];
    rc = new int[cap];
    cnt = new int[cap];
    int[] head = new int[n], next = new int[n];
    java.util.Arrays.fill(head, -1);
    for (int i = 1; i < n; i++) {
      next[i] = head[par[i]];
      head[par[i]] = i;
    }
    int[] order = new int[n], xr = new int[n];
    int qh = 0, qt = 0;
    order[qt++] = 0;
    xr[0] = vals[0];
    while (qh < qt) {
      int u = order[qh++];
      for (int c = head[u]; c >= 0; c = next[c]) {
        xr[c] = xr[u] ^ vals[c];
        order[qt++] = c;
      }
    }
    int[] qHead = new int[n], qNext = new int[queries.length];
    java.util.Arrays.fill(qHead, -1);
    for (int i = 0; i < queries.length; i++) {
      qNext[i] = qHead[queries[i][0]];
      qHead[queries[i][0]] = i;
    }
    int[] root = new int[n], ans = new int[queries.length];
    for (int i = 0; i < n; i++) root[i] = insertSingle(xr[i]);
    for (int idx = n - 1; idx >= 0; idx--) {
      int u = order[idx];
      for (int q = qHead[u]; q >= 0; q = qNext[q]) {
        int k = queries[q][1];
        if (cnt[root[u]] < k) {
          ans[q] = -1;
          continue;
        }
        int cur = root[u], val = 0;
        for (int b = BITS - 1; b >= 0; b--) {
          if (cnt[lc[cur]] >= k) {
            cur = lc[cur];
          } else {
            k -= cnt[lc[cur]];
            cur = rc[cur];
            val |= 1 << b;
          }
        }
        ans[q] = val;
      }
      if (u != 0) root[par[u]] = merge(root[par[u]], root[u], BITS);
    }
    return ans;
  }

  private int insertSingle(int val) {
    int root = nodes++, cur = root;
    for (int b = BITS - 1; b >= 0; b--) {
      int nd = nodes++;
      if ((val >> b & 1) == 0) lc[cur] = nd;
      else rc[cur] = nd;
      cur = nd;
    }
    cnt[cur] = 1;
    cur = root;
    for (int b = BITS - 1; b >= 0; b--) {
      cnt[cur] = 1;
      cur = (val >> b & 1) == 0 ? lc[cur] : rc[cur];
    }
    return root;
  }
}
